    const hs = (x, y, L) => `${x},${y} ${x + t / 2},${y - t / 2} ${x + L - t / 2},${y - t / 2} ${x + L},${y} ${x + L - t / 2},${y + t / 2} ${x + t / 2},${y + t / 2}`;
    const vs = (x, y, L) => `${x},${y} ${x + t / 2},${y + t / 2} ${x + t / 2},${y + L - t / 2} ${x},${y + L} ${x - t / 2},${y + L - t / 2} ${x - t / 2},${y + t / 2}`;
