      ctl = ce("div", "tg");
      const row = ce("div", "swrow"); row.append(lab("Power"), jamSwitch({on, label: `${name} power`, kind: "plug", accent: c.switch_accent, big: kio, onToggle: power}));
      ctl.append(row);
