      if (k === "power") { card._power(); return; }
      if (rc.actions && rc.actions[k]) { runAction(card, card._hass, rc.actions[k], rc.entity); return; }
      if (!rc.entity) return;
      const cmd = (rc.commands && rc.commands[k]) || JAM_REMOTE_CMDS[k];
