    const y = v => mt + (tk.hi - Math.min(tk.hi, Math.max(tk.lo, v))) / (tk.hi - tk.lo) * (H - mt - mb);
    return {W, H, ml, mr, mt, mb, x, y, tk, fmt, per, style};
