      if (v === null) marks[i].setAttribute("visibility", "hidden");
      else { marks[i].removeAttribute("visibility"); marks[i].setAttribute("x", xx - 4); marks[i].setAttribute("y", Math.round((g.ys ? g.ys[i] : g.y)(v)) - 4); }
