      m.append(rgSvg("rect", {x: -4, y: -4, width: W + 8, height: H + 8, fill: "white"}));
      for (let j = i + 1; j < shapes.length; j++) m.append(rgSvg("path", {d: shapes[j].area, fill: "black", stroke: "black", "stroke-width": 3}));
